package com.vex.videoai.data
import org.json.JSONArray
import org.json.JSONObject
import java.util.UUID
data class SceneLayer(val id:String=UUID.randomUUID().toString(),val name:String,val kind:String="object",val x:Float=.5f,val y:Float=.5f,val scale:Float=1f,val visible:Boolean=true,val assetPath:String="")
data class SubtitleLine(val id:String=UUID.randomUUID().toString(),val startMs:Long,val endMs:Long,val text:String)
data class VideoScene(val id:String=UUID.randomUUID().toString(),val title:String,val durationSeconds:Int=6,val narration:String="",val dialogue:String="",val visualDescription:String="",val cameraMovement:String="Static",val transition:String="Cut",val layers:List<SceneLayer> = emptyList(),val subtitles:List<SubtitleLine> = emptyList(),val voiceoverPath:String="",val soundEffects:List<String> = emptyList())
data class VideoProject(val id:String=UUID.randomUUID().toString(),val title:String,val idea:String,val category:String,val durationSeconds:Int,val aspectRatio:String,val visualStyle:String,val createdAt:Long=System.currentTimeMillis(),val scenes:List<VideoScene> = emptyList()) {
 fun toJson()=JSONObject().apply { put("id",id);put("title",title);put("idea",idea);put("category",category);put("durationSeconds",durationSeconds);put("aspectRatio",aspectRatio);put("visualStyle",visualStyle);put("createdAt",createdAt);put("scenes",JSONArray().apply { scenes.forEach { put(it.toJson()) } }) }
 companion object { fun fromJson(j:JSONObject):VideoProject { val a=j.optJSONArray("scenes")?:JSONArray();return VideoProject(j.optString("id",UUID.randomUUID().toString()),j.optString("title","Untitled project"),j.optString("idea"),j.optString("category","story"),j.optInt("durationSeconds",45),j.optString("aspectRatio","9:16"),j.optString("visualStyle","Cinematic"),j.optLong("createdAt",System.currentTimeMillis()),(0 until a.length()).mapNotNull { a.optJSONObject(it)?.let(::sceneFromJson) }) } }
}
private fun VideoScene.toJson()=JSONObject().apply { put("id",id);put("title",title);put("durationSeconds",durationSeconds);put("narration",narration);put("dialogue",dialogue);put("visualDescription",visualDescription);put("cameraMovement",cameraMovement);put("transition",transition);put("layers",JSONArray().apply { layers.forEach { l->put(JSONObject().apply { put("id",l.id);put("name",l.name);put("kind",l.kind);put("x",l.x.toDouble());put("y",l.y.toDouble());put("scale",l.scale.toDouble());put("visible",l.visible);put("assetPath",l.assetPath) }) } });put("subtitles",JSONArray().apply { subtitles.forEach { cue->put(JSONObject().apply { put("id",cue.id);put("startMs",cue.startMs);put("endMs",cue.endMs);put("text",cue.text) }) } });put("voiceoverPath",voiceoverPath);put("soundEffects",JSONArray().apply{soundEffects.forEach{put(it)}}) }
private fun sceneFromJson(j:JSONObject):VideoScene { val a=j.optJSONArray("layers")?:JSONArray();val layers=(0 until a.length()).mapNotNull { a.optJSONObject(it)?.let { l->SceneLayer(l.optString("id",UUID.randomUUID().toString()),l.optString("name","Layer"),l.optString("kind","object"),l.optDouble("x",.5).toFloat(),l.optDouble("y",.5).toFloat(),l.optDouble("scale",1.0).toFloat(),l.optBoolean("visible",true),l.optString("assetPath")) } };val subtitlesArray=j.optJSONArray("subtitles")?:JSONArray();val subtitles=(0 until subtitlesArray.length()).mapNotNull { subtitlesArray.optJSONObject(it)?.let { cue->SubtitleLine(cue.optString("id",UUID.randomUUID().toString()),cue.optLong("startMs"),cue.optLong("endMs"),cue.optString("text")) } };val soundArray=j.optJSONArray("soundEffects")?:JSONArray();val soundEffects=(0 until soundArray.length()).map{soundArray.optString(it)}.filter{it.isNotBlank()};return VideoScene(j.optString("id",UUID.randomUUID().toString()),j.optString("title","Scene"),j.optInt("durationSeconds",6).coerceIn(1,120),j.optString("narration"),j.optString("dialogue"),j.optString("visualDescription"),j.optString("cameraMovement","Static"),j.optString("transition","Cut"),layers,subtitles,j.optString("voiceoverPath"),soundEffects) }
